import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  async headers() {
    const immutableMedia = {
      key: "Cache-Control",
      value: "public, max-age=31536000, immutable",
    };
    // Fingerprinted or append-only media: filenames change when bytes
    // change, so browsers may cache for a year and never re-download
    // on back-navigation. (If you ever replace dp.webp in place,
    // rename it or drop the immutable flag for that path.)
    return [
      // case-study media (generated by scripts/build-images.mjs). Not
      // under /work: those paths are the HTML pages themselves.
      { source: "/img/:path*", headers: [immutableMedia] },
      { source: "/gallery/:all", headers: [immutableMedia] },
      { source: "/lab/:all", headers: [immutableMedia] },
      { source: "/music/:all", headers: [immutableMedia] },
      { source: "/company-logos/:all", headers: [immutableMedia] },
      { source: "/pfps/:all", headers: [immutableMedia] },
      { source: "/avatar/:all", headers: [immutableMedia] },
      { source: "/sounds/:all", headers: [immutableMedia] },
    ];
  },
  async redirects() {
    return [
      // The old 21-section gallery is superseded by the seven case
      // studies; keep inbound links and search results working.
      { source: "/designs", destination: "/#work", permanent: true },
      // The homepage is the work index.
      { source: "/work", destination: "/#work", permanent: false },
    ];
  },
};

export default nextConfig;
